on('create', () => {
  input.requestPointerLock();
  game.camera.setMode('first-person');
  game.camera.follow(self, { distance: 0, height: 0.8 });
  game.playSong('DungeonTheme', { loop: true, volume: 1, fadeIn: 0 });
  game.setText('hud', 'Cles: 0  |  Explorez le donjon (Z,Q,S,D + Souris)', 10, 10);
});
on('update', (dt) => {
  self.rotateY((input.mouseDeltaX || 0) * 0.15);
  if (input.isDown('W')) {
    self.moveForward(6);
    if (input.isDown('S')) {
      self.moveForward(-6);
      if (input.isDown('A')) {
        self.moveRight(-5);
        if (input.isDown('D')) {
          self.moveRight(5);
          if (input.justPressed('SPACE')) {
            self.jump(10);
          }
