on('update', (dt) => {
  self.rotateY(3);
});
on('overlap', 'Player', (other) => {
  self.destroy();
  game.score += 1;
  game.playSound('blip', 1, 1);
  game.setText('hud', 'Cle trouvee ! Vous pouvez ouvrir la grande porte !', 10, 10);
});

on('overlap', 'Player', (other) => {
  if (game.score >= 1) {
    game.playSound('portal', 1, 1);
    self.destroy();
    game.setText('hud', 'La porte de pierre s ouvre dans un grondement !', 10, 10);
  } else {
    game.setText('hud', 'Porte verrouillee... Trouvez la cle d or dans les alcoves !', 10, 10);
  }
});

